<script setup lang="ts">
import {computed} from 'vue';import type {Scenario} from '../types';import {analyzeDraws} from '../engine/draws';import {label,red} from '../engine/cards';const props=defineProps<{scenario:Scenario}>();const analysis=computed(()=>analyzeDraws(props.scenario.hole.filter((c):c is number=>c!==null),props.scenario.board.filter((c):c is number=>c!==null)));
